// Category B — a heading group with no behaviour: an optional eyebrow, the step's title, and an optional
// description. It opens a customer-facing step in an ordering flow (a counter, a kiosk, a payment
// terminal, a table order), and the blocks built on those steps reuse it.
//
// The eyebrow takes the `body` role, emphasized, not a dedicated eyebrow role: in these screens it is
// the first clause of the message the title finishes ("825 P 적립을 위해" + "휴대폰 번호를 입력해주세요"),
// which is reading content (naming-convention.md § type roles, row 3), so no eyebrow role is needed.
//
// Two firsts, both deliberate. This is the first consumer of an emphasized title rung and the first
// of the body-emphasized eyebrow: a step screen sets the title heavier than body text and the
// eyebrow as a stressed clause of the same sentence.
//
// The root is a div, not <header>: outside sectioning content <header> is a banner landmark, and a
// step screen already sits in an app shell that has one (PageHeader does the same).
//
// The slots are named by role, not position, because a step template may swap which line is the
// title and which the subtitle.
import { Heading } from "react-aria-components";
import type { ReactNode, Ref } from "react";
import "./StepHeader.css";

type StepHeaderSize = "small" | "medium" | "large";

export interface StepHeaderProps {
  /**
   * Size axis: the type rung of every part.
   *
   * @default "medium"
   */
  size?: StepHeaderSize;
  /**
   * Alignment. `center` for a customer screen, `start` inside a staff dialog or panel.
   *
   * @default "start"
   */
  align?: "start" | "center";
  /** The context line above the title, e.g. the amount due. Rendered in the brand ink. */
  eyebrow?: ReactNode;
  /** The step's title: what the person is asked to do. Wrap a part in `StepHeaderEmphasis` to stress it. */
  title: ReactNode;
  /** One or two lines under the title. */
  description?: ReactNode;
  /**
   * Heading level of the title.
   *
   * @default 2
   */
  level?: 1 | 2 | 3;
  /** Id of the title heading, so a surrounding section can be named by the title alone. */
  id?: string;
  /** Additional class (optional). sd-step-header is always preserved. */
  className?: string;
  /** Forwarded to the root element. */
  ref?: Ref<HTMLDivElement>;
}

export function StepHeader({
  size = "medium",
  align = "start",
  eyebrow,
  title,
  description,
  level = 2,
  id,
  className,
  ref,
}: StepHeaderProps) {
  return (
    <div
      ref={ref}
      data-align={align}
      className={className ? `sd-step-header ${className}` : "sd-step-header"}
    >
      <div className="sd-step-header__heading" data-align={align}>
        {eyebrow != null && <p className={`sd-step-header__eyebrow sd-type-body-${size}-emphasized`}>{eyebrow}</p>}
        <Heading id={id} level={level} className={`sd-step-header__title sd-type-title-${size}-emphasized`}>
          {title}
        </Heading>
      </div>
      {description != null && <p className={`sd-step-header__description sd-type-body-${size}`}>{description}</p>}
    </div>
  );
}

export interface StepHeaderEmphasisProps {
  children?: ReactNode;
  /** Additional class (optional). sd-step-header__emphasis is always preserved. */
  className?: string;
}

/** Stresses a span of the title in the brand ink, e.g. the points in "825P를 적립할게요". */
export function StepHeaderEmphasis({ children, className }: StepHeaderEmphasisProps) {
  return (
    <span className={className ? `sd-step-header__emphasis ${className}` : "sd-step-header__emphasis"}>{children}</span>
  );
}

/* A heading group: the eyebrow and title read as one unit, so they share a parent and a tighter gap
   than the gap to the description (heading-pair rule, check-heading-pair.mjs). */
.sd-step-header {
  display: flex;
  flex-direction: column;
  gap: var(--sd-step-header-gap);
  margin: 0;
}

.sd-step-header[data-align="center"] {
  align-items: center;
  text-align: center;
}

.sd-step-header__heading {
  display: flex;
  flex-direction: column;
  gap: var(--sd-step-header-heading-gap);
}

.sd-step-header__heading[data-align="center"] {
  align-items: center;
}

.sd-step-header__eyebrow {
  margin: 0;
  color: var(--sd-step-header-eyebrow-foreground);
}

.sd-step-header__title {
  margin: 0;
  color: var(--sd-step-header-title-foreground);
  text-wrap: balance;
}

.sd-step-header__description {
  margin: 0;
  color: var(--sd-step-header-description-foreground);
}

.sd-step-header__emphasis {
  color: var(--sd-step-header-emphasis-foreground);
}
